// Feed Service: fan-out-on-write timeline generation using Redis sorted sets
var builder = WebApplication.CreateBuilder(args);

builder.Services.AddStackExchangeRedisCache(opt =>
    opt.Configuration = builder.Configuration.GetConnectionString("Redis")
);

var app = builder.Build();

app.MapPost("/tweets", async (CreateTweetRequest req, IRedisCache cache) => {
    // 1. Persist tweet in primary database (Post Service handles this)
    //    This endpoint is called by the Post Service after tweet is saved
    var tweetId = req.TweetId;
    var authorId = req.AuthorId;

    // 2. Fan-out: push tweet ID to all followers' home timelines
    //    Followers are retrieved from User Service; use pipeline for batching
    var followerIds = await userService.GetFollowerIdsAsync(authorId);
    var timelineKey = $"timeline:{followerId}";
    var pipeline = cache.CreateMultiplexer().GetDatabase().Multi();
    foreach (var followerId in followerIds)
    {
        pipeline.SortedSetAddAsync(
            $"timeline:{followerId}",
            tweetId,
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
        );
        // Trim timeline to keep only the latest 1,000 tweets per user
        pipeline.SortedSetRemoveRangeByRankAsync(
            $"timeline:{followerId}",
            0, -1001
        );
    }
    await pipeline.ExecuteAsync();

    return Results.Created($"/tweets/{tweetId}", new { tweetId });
})
.WithName("FanOutTweet");

app.MapGet("/timeline/{userId}", async (string userId, IRedisCache cache) => {
    var tweetIds = await cache.SortedSetRangeByRankAsync(
        $"timeline:{userId}",
        0, 49,
        Order.Descending
    );
    return Results.Ok(new { tweetIds });
})
.WithName("GetTimeline");

app.MapGet("/health", () => Results.Ok());
app.Run();
